package pe.edu.utp.eventope.controller;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import pe.edu.utp.eventope.dto.*;import pe.edu.utp.eventope.util.Csrf;import java.io.IOException;import java.util.*;
@WebServlet(urlPatterns={"/compras/revision","/compras/nominacion"})
public final class RevisionCompraServlet extends HttpServlet {
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{CarritoCompra c=(CarritoCompra)req.getSession().getAttribute("carritoCompra");if(c==null){resp.sendRedirect(req.getContextPath()+"/carrito");return;}c.asegurarClave();req.setAttribute("carrito",c);req.setAttribute("csrf",Csrf.token(req.getSession()));req.getRequestDispatcher("/WEB-INF/views/compras/revision.jsp").forward(req,resp);}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{req.setCharacterEncoding("UTF-8");if(!Csrf.valido(req.getSession(false),req.getParameter("csrf"))){resp.sendError(403,"Token de seguridad inválido");return;}CarritoCompra c=(CarritoCompra)req.getSession().getAttribute("carritoCompra");if(c==null){resp.sendRedirect(req.getContextPath()+"/carrito");return;}try{List<NominacionAsistente> lista=new ArrayList<>();for(int i=0;i<c.getCantidadTotal();i++)lista.add(new NominacionAsistente(req.getParameter("dni_"+i),req.getParameter("nombres_"+i),req.getParameter("apellidos_"+i)));c.setNominaciones(lista);c.asegurarClave();resp.sendRedirect(req.getContextPath()+"/compras/revision");}catch(IllegalArgumentException e){req.setAttribute("error",e.getMessage());req.setAttribute("carrito",c);req.setAttribute("csrf",Csrf.token(req.getSession()));req.getRequestDispatcher("/WEB-INF/views/compras/revision.jsp").forward(req,resp);}}
}
